import {createRequire} from 'node:module';import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';
const require=createRequire(new URL('../.tmp-order-workbook/package.json',import.meta.url));const {chromium}=require('playwright');const browser=await chromium.launch({channel:'chrome',headless:true});
try{
 const page=await browser.newPage({viewport:{width:1440,height:1100}});const errors=[];page.on('pageerror',e=>errors.push(e.message));let admin=false;let archives=0;
 const tasks=[{Id:1,Ticket:'DEV-000001',Usuario:'worker',Creador:'worker',Titulo:'Verified daily work fixture',Estado:'pendiente',Prioridad:'normal',Inicio:'2026-10-21 08:00:00',Fin:'2026-10-21 18:00:00',Repeticion:'ninguna',Segundos:0,Objetivo:0,Version:1,Archivada:0},{Id:2,Ticket:'DEV-000002',Usuario:'worker',Creador:'worker',Titulo:'Completed fixture',Estado:'concluida',Prioridad:'normal',Inicio:'2026-10-21 08:00:00',Fin:'2026-10-21 18:00:00',FinReal:'2026-10-21 17:00:00',Repeticion:'ninguna',Segundos:60,Objetivo:0,Version:1,Archivada:0}];
 const person={id:1,user:'worker',assigned:3,pending:1,attended:2,resolved_events:2,work_minutes:90,worklogs:2,response_count:2,response_average:5,resolution_count:2,resolution_average:40,rating:4.5,ratings:2};
 await page.route('**/*',async route=>{const u=new URL(route.request().url());if(u.hostname!=='ticket.local')return route.fulfill({status:204,body:''});if(u.pathname.startsWith('/nuevo/')){const f=path.resolve('dist',decodeURIComponent(u.pathname.slice(7)));assert.ok(f.startsWith(path.resolve('dist')+path.sep));if(!fs.existsSync(f))return route.fulfill({status:404,body:''});return route.fulfill({body:fs.readFileSync(f),contentType:{'.html':'text/html','.js':'application/javascript','.css':'text/css','.svg':'image/svg+xml'}[path.extname(f)]||'application/octet-stream'});}
  const p=u.pathname;
  if(p.endsWith('/diario/contexto'))return route.fulfill({json:{user:admin?'superadmin':'worker',nombre:'Fixture user',perfil:admin?'ADMIN':'PROGRAMADOR',programador:!admin,superadmin:admin,admin,csrf:'fixture',usuarios:[{Usuario:'worker',NombreUsuario:'Worker'}],empleados:[]}});
  if(p.endsWith('/diario/tareas')&&route.request().method()==='GET')return route.fulfill({json:{tareas:tasks.filter(t=>!t.Archivada),indicadores:tasks,limitado:false}});
  if(p.endsWith('/diario/tareas/2')&&route.request().method()==='POST'){archives++;tasks[1].Archivada=1;return route.fulfill({json:{ok:true}});}
  if(p.endsWith('/support/context'))return route.fulfill({json:{user:admin?'superadmin':'worker',principal:1,superadmin:admin,tenant:1,tenants:[],categories:[],roles:[{role:'technician'}],csrf:'fixture'}});
  if(p.endsWith('/support/performance'))return route.fulfill({json:{from:'2026-10-01',to:'2026-10-21',team:[person],daily:[{date:'2026-10-21',user:'worker',work_minutes:90,response_count:2,resolved_events:2}],evidence:[],evidence_total:0,reviews:[]}});
  if(p.endsWith('/diario/dashboard'))return route.fulfill({json:{resumen:{total:0,concluidas:0,validadas:0,calidad:null,vencidas:0,logro:0},equipo:[],estados:{},calificaciones:{},actividades:[],pagina:1,paginas:1}});
  if(p.endsWith('/diario/tickets-reporte')||p.endsWith('/support/report'))return route.fulfill({json:{rows:[],summary:[],total:0,next:null}});
  if(p.endsWith('/diario/avances'))return route.fulfill({json:{diario:[],por_usuario:[],avances:[]}});
  if(p.endsWith('/support/activity'))return route.fulfill({json:{diario:[],tickets:[],trabajos:[],minutos:0,urgentes:{total:0,tickets:[]}}});
  if(p.endsWith('/support/notifications'))return route.fulfill({json:{unread:0,notifications:[],urgent_tickets:[],urgent_total:0}});
  if(p.endsWith('/diario/recordatorios'))return route.fulfill({json:{tareas:[],ahora:'2026-10-21 08:00:00'}});
  if(p.endsWith('/diario/soporte/diario'))return route.fulfill({json:{dias:[]}});
  return route.fulfill({json:[]});
 });
 await page.goto('http://ticket.local/nuevo/index.html#/diario',{waitUntil:'domcontentloaded'});await page.getByRole('button',{name:'Verified daily work fixture',exact:true}).waitFor();const order=await page.evaluate(()=>({board:document.querySelector('.diary-board-shell').getBoundingClientRect().top,statistics:document.querySelector('.work-area').getBoundingClientRect().top}));assert.ok(order.board<order.statistics,'Compiled screen must put board before statistics');
 page.once('dialog',d=>d.dismiss());await page.locator('.lane-concluida').getByRole('button',{name:'Archivar',exact:true}).click();assert.equal(archives,0);page.once('dialog',d=>d.accept());await page.locator('.lane-concluida').getByRole('button',{name:'Archivar',exact:true}).click();await page.waitForFunction(()=>!document.querySelector('.lane-concluida .diary-board-card'));assert.equal(archives,1);
 fs.mkdirSync('tmp/ticket-center',{recursive:true});await page.screenshot({path:'tmp/ticket-center/board-desktop.png',fullPage:true});await page.setViewportSize({width:393,height:852});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true,'Compiled mobile width');await page.screenshot({path:'tmp/ticket-center/board-mobile.png',fullPage:true});
 admin=true;await page.setViewportSize({width:1440,height:1100});await page.reload();await page.getByRole('button',{name:'Reportes e indicadores por empleado',exact:true}).click();await page.getByRole('heading',{name:'Rendimiento y evaluación del equipo de soporte',exact:true}).waitFor();await page.locator('.performance-panel canvas').first().waitFor();await page.screenshot({path:'tmp/ticket-center/performance-desktop.png',fullPage:true});assert.deepEqual(errors,[]);
 console.log('PASS compiled board-first screen, archive cancel/confirm, mobile width, superadmin performance with real charts and existing internal dashboard. HTTP mocked.');
}finally{await browser.close();}
